// pages/dashboard/AdminDashboard.js - VERSION AVEC IMAGES GARANTIES
import React, { useState } from 'react';
import { useAuthContext } from '../../hooks/useAuthContext';
import { useAdmin } from '../../hooks/UseAdmin';
import { useCourseContext } from '../../context/CourContext';
import './admindashboard.css';

const AdminDashboard = () => {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();
  const { courses, addCourse, deleteCourse } = useCourseContext();
  
  const [activeTab, setActiveTab] = useState('overview');
  const [showNewCourseForm, setShowNewCourseForm] = useState(false);
  const [newCourse, setNewCourse] = useState({
    title: '',
    category: 'Développement', // ← Catégorie par défaut
    instructor: '',
    price: '',
    originalPrice: '',
    description: '',
    status: 'published', // ← Publié par défaut
    level: 'intermediaire',
    featured: false
  });

  // FONCTION POUR OBTENIR UNE IMAGE GARANTIE
  const getDefaultImage = (category) => {
    const defaultImages = {
      'Développement': 'https://via.placeholder.com/300x200/667eea/ffffff?text=Développement',
      'Design': 'https://via.placeholder.com/300x200/764ba2/ffffff?text=Design',
      'Business': 'https://via.placeholder.com/300x200/f093fb/ffffff?text=Business',
      'Marketing': 'https://via.placeholder.com/300x200/4facfe/ffffff?text=Marketing'
    };
    return defaultImages[category] || 'https://via.placeholder.com/300x200/667eea/ffffff?text=Cours+EduPlatform';
  };

  const handleSubmitCourse = (e) => {
    e.preventDefault();
    
    // Calculer le prix original si non fourni
    let originalPriceValue = newCourse.originalPrice;
    if (!originalPriceValue && newCourse.price) {
      originalPriceValue = Math.round(parseFloat(newCourse.price) * 1.3).toString();
    }

    const courseData = {
      title: newCourse.title,
      category: newCourse.category,
      instructor: newCourse.instructor,
      price: parseInt(newCourse.price) || 0,
      originalPrice: parseInt(originalPriceValue) || 0,
      description: newCourse.description,
      status: newCourse.status,
      level: newCourse.level,
      featured: newCourse.featured,
      rating: 4.5,
      students: 0,
      duration: "10h 00min",
      // IMAGE GARANTIE
      image: getDefaultImage(newCourse.category)
    };

    console.log('🆕 Cours créé avec image:', courseData.image);

    addCourse(courseData);
    
    // Réinitialiser le formulaire
    setNewCourse({
      title: '',
      category: 'Développement',
      instructor: '',
      price: '',
      originalPrice: '',
      description: '',
      status: 'published',
      level: 'intermediaire',
      featured: false
    });
    
    setShowNewCourseForm(false);
    alert('✅ Cours créé avec succès !');
  };

  // ... (le reste de votre code reste identique)

  return (
    <div className="admin-dashboard">
      {/* ... (votre JSX existant) */}

      {/* MODAL SIMPLIFIÉ - RETIRER LA SECTION IMAGE COMPLIQUÉE */}
      {showNewCourseForm && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Créer un Nouveau Cours</h3>
              <button className="btn-icon" onClick={() => setShowNewCourseForm(false)}>
                ✕
              </button>
            </div>
            <form onSubmit={handleSubmitCourse}>
              <div className="form-group">
                <label>Titre du cours *</label>
                <input
                  type="text"
                  name="title"
                  value={newCourse.title}
                  onChange={(e) => setNewCourse(prev => ({...prev, title: e.target.value}))}
                  required
                  placeholder="Ex: React Avancé - Les Hooks"
                />
              </div>
              
              <div className="form-group">
                <label>Catégorie *</label>
                <select
                  name="category"
                  value={newCourse.category}
                  onChange={(e) => setNewCourse(prev => ({...prev, category: e.target.value}))}
                  required
                >
                  <option value="Développement">Développement</option>
                  <option value="Design">Design</option>
                  <option value="Business">Business</option>
                  <option value="Marketing">Marketing</option>
                </select>
              </div>
              
              <div className="form-group">
                <label>Formateur *</label>
                <input
                  type="text"
                  name="instructor"
                  value={newCourse.instructor}
                  onChange={(e) => setNewCourse(prev => ({...prev, instructor: e.target.value}))}
                  required
                  placeholder="Ex: Ahmed Ben Ali"
                />
              </div>

              {/* INFO IMAGE AUTOMATIQUE */}
              <div style={{
                background: '#e3f2fd',
                padding: '10px',
                borderRadius: '6px',
                marginBottom: '15px',
                textAlign: 'center'
              }}>
                <div>🖼️ <strong>Image automatique</strong></div>
                <div style={{ fontSize: '0.8em', color: '#1565c0' }}>
                  Une image sera générée automatiquement selon la catégorie
                </div>
              </div>

              {/* ... (le reste de votre formulaire) */}
            </form>
          </div>
        </div>
      )}

      {/* ... (le reste de votre JSX) */}
    </div>
  );
};

export default AdminDashboard;
